-- The pack items (server/README.md "Pack items and monsters"): eating the new food. The ids come from
-- data/lib/chaos_pack_items.lua (generated by server/tools/install_pack_items.py --lua); the items themselves exist after
-- the install step "packitems". Same rules as the stock food: food[1] x 12 seconds of regeneration, at most 1200 s.
if not ChaosPackItems then
	dofile("data/lib/chaos_pack_items.lua")
end

local eat = Action()

function eat.onUse(player, item, fromPosition, target, toPosition, isHotkey)
	local food = ChaosPackItems.food[item:getId()]
	if not food then
		return false
	end
	local condition = player:getCondition(CONDITION_REGENERATION, CONDITIONID_DEFAULT)
	if condition and math.floor(condition:getTicks() / 1000 + food[1] * 12) >= 1200 then
		player:sendTextMessage(MESSAGE_STATUS_SMALL, "You are full.")
		return true
	end
	player:feed(food[1] * 12)
	player:say(food[2], TALKTYPE_MONSTER_SAY)
	item:remove(1)
	return true
end

local n = 0
for id in pairs(ChaosPackItems.food) do
	if ItemType(id):getId() ~= 0 then
		eat:id(id)
		n = n + 1
	end
end
if n > 0 then
	eat:register()
end
